          title: "Python 实验：正交对角化的数值实现与验证",
          code: "import math\n\n\ndef transpose(A):\n    return [list(col) for col in zip(*A)]\n\n\ndef matmul(A, B):\n    return [[sum(A[i][t] * B[t][j] for t in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]\n\n\ndef jacobi(A, sweeps=100):\n    '''对称矩阵的特征分解：返回 (特征值降序列表, 特征向量矩阵 Q)。\n    Q 的第 i 列是第 i 个特征值对应的单位特征向量。'''\n    n = len(A)\n    a = [row[:] for row in A]\n    Q = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]\n    for _ in range(sweeps):\n        off = sum(a[p][q] ** 2 for p in range(n) for q in range(p + 1, n))\n        if off < 1e-24:\n            break\n        for p in range(n):\n            for q in range(p + 1, n):\n                if abs(a[p][q]) < 1e-18:\n                    continue\n                # 消去 a[p][q] 的旋转角，标准 Jacobi 公式\n                theta = 0.5 * math.atan2(2.0 * a[p][q], a[q][q] - a[p][p])\n                c, s = math.cos(theta), math.sin(theta)\n                for k in range(n):                      # 列变换\n                    akp, akq = a[k][p], a[k][q]\n                    a[k][p] = c * akp - s * akq\n                    a[k][q] = s * akp + c * akq\n                for k in range(n):                      # 行变换\n                    apk, aqk = a[p][k], a[q][k]\n                    a[p][k] = c * apk - s * aqk\n                    a[q][k] = s * apk + c * aqk\n                for k in range(n):                      # 累积旋转：Q <- Q * R\n                    qkp, qkq = Q[k][p], Q[k][q]\n                    Q[k][p] = c * qkp - s * qkq\n                    Q[k][q] = s * qkp + c * qkq\n    pairs = sorted(((a[i][i], [Q[k][i] for k in range(n)]) for i in range(n)), key=lambda pr: -pr[0])\n    lam = [pr[0] for pr in pairs]\n    Qs = [[pairs[j][1][i] for j in range(n)] for i in range(n)]\n    return lam, Qs\n\n\nS = [[2.0, 1.0, 0.0], [1.0, 2.0, 0.0], [0.0, 0.0, 3.0]]\nlam, Q = jacobi(S)\nprint('S =', S)\nprint('特征值（降序）=', [round(x, 6) for x in lam])\nprint('Q（列 = 单位特征向量）:')\nfor row in Q:\n    print('   ', [round(x, 6) for x in row])\nQt = transpose(Q)\nprint('Q^T Q   =', [[round(x, 6) for x in row] for row in matmul(Qt, Q)])\nprint('Q^T S Q =', [[round(x, 6) for x in row] for row in matmul(matmul(Qt, S), Q)])\n# 逐个核对残差 ||S q_i - lam_i q_i||\nfor i in range(3):\n    qi = [Q[r][i] for r in range(3)]\n    Sqi = [sum(S[r][c] * qi[c] for c in range(3)) for r in range(3)]\n    res = math.sqrt(sum((Sqi[r] - lam[i] * qi[r]) ** 2 for r in range(3)))\n    print('第 %d 个特征对：lam = %.6f，残差 = %.2e' % (i, lam[i], res))\n"
