          code: "import math\n\n\ndef transpose(A):\n    return [list(col) for col in zip(*A)]\n\n\ndef matmul(A, B):\n    return [[sum(A[i][t] * B[t][j] for t in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]\n\n\ndef jacobi(A, sweeps=100):\n    '''对称矩阵特征分解，返回 (特征值, 特征向量) 的列表，按特征值降序，每个特征向量是单位列向量。'''\n    n = len(A)\n    a = [row[:] for row in A]\n    Q = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]\n    for _ in range(sweeps):\n        off = sum(a[p][q] ** 2 for p in range(n) for q in range(p + 1, n))\n        if off < 1e-24:\n            break\n        for p in range(n):\n            for q in range(p + 1, n):\n                if abs(a[p][q]) < 1e-18:\n                    continue\n                theta = 0.5 * math.atan2(2.0 * a[p][q], a[q][q] - a[p][p])\n                c, s = math.cos(theta), math.sin(theta)\n                for k in range(n):\n                    akp, akq = a[k][p], a[k][q]\n                    a[k][p] = c * akp - s * akq\n                    a[k][q] = s * akp + c * akq\n                for k in range(n):\n                    apk, aqk = a[p][k], a[q][k]\n                    a[p][k] = c * apk - s * aqk\n                    a[q][k] = s * apk + c * aqk\n                for k in range(n):\n                    qkp, qkq = Q[k][p], Q[k][q]\n                    Q[k][p] = c * qkp - s * qkq\n                    Q[k][q] = s * qkp + c * qkq\n    pairs = sorted(((a[i][i], [Q[k][i] for k in range(n)]) for i in range(n)), key=lambda pr: -pr[0])\n    return pairs\n\n\ndef svd(A):\n    '''只用 A^T A 的特征分解构造 SVD：A 是 m x n，返回 (左奇异向量, 奇异值, 右奇异向量) 三组降序列表。'''\n    m, n = len(A), len(A[0])\n    AtA = matmul(transpose(A), A)\n    pairs = jacobi(AtA)\n    sigma = [max(0.0, pr[0]) ** 0.5 for pr in pairs]\n    Ucols = []\n    Vcols = []\n    for s, v in zip(sigma, [pr[1] for pr in pairs]):\n        Av = [sum(A[r][c] * v[c] for c in range(n)) for r in range(m)]\n        Ucols.append([x / s for x in Av] if s > 1e-12 else [0.0] * m)\n        Vcols.append(v)\n    return Ucols, sigma, Vcols\n\n\nA = [[1.0, 1.0], [1.0, 2.0], [1.0, 3.0]]\nAtA = matmul(transpose(A), A)\ndetAtA = AtA[0][0] * AtA[1][1] - AtA[0][1] * AtA[1][0]\nUcols, sigma, Vcols = svd(A)\nprint('A^T A =', [[round(x, 6) for x in row] for row in AtA])\nprint('trace =', round(sum(AtA[i][i] for i in range(2)), 6), ' det =', round(detAtA, 6), ' 判别式 =', round(17.0 ** 2 - 4 * detAtA, 6))\nprint('sigma =', [round(x, 6) for x in sigma])\nprint('sigma1^2 + sigma2^2 =', round(sum(x * x for x in sigma), 6), ' 应等于 ||A||_F^2 =', round(sum(x * x for row in A for x in row), 6))\nprint('sigma1 * sigma2 =', round(sigma[0] * sigma[1], 6), ' 应等于 sqrt(det A^T A) =', round(math.sqrt(detAtA), 6))\nfor i in range(2):\n    print('sigma%d = %.6f' % (i + 1, sigma[i]))\n    print('   v%d =' % (i + 1), [round(x, 6) for x in Vcols[i]])\n    print('   u%d =' % (i + 1), [round(x, 6) for x in Ucols[i]])\nfor k in (1, 2):\n    R = [[0.0] * 2 for _ in range(3)]\n    for i in range(k):\n        for r in range(3):\n            for c in range(2):\n                R[r][c] += sigma[i] * Ucols[i][r] * Vcols[i][c]\n    err = math.sqrt(sum((A[r][c] - R[r][c]) ** 2 for r in range(3) for c in range(2)))\n    tail = math.sqrt(sum(x * x for x in sigma[k:]))\n    print('rank %d 逼近：误差 = %.6f，被丢弃奇异值平方和开根 = %.6f' % (k, err, tail))\n"
